def hasPathSum(root, targetSum):
    if not root: return False
    queue = deque([(root, targetSum - root.val)])
    while queue:
        node, remaining = queue.popleft()
        if not node.left and not node.right and remaining == 0:
            return True
        if node.left: queue.append((node.left, remaining - node.left.val))
        if node.right: queue.append((node.right, remaining - node.right.val))
    return False

def averageOfSubtree(root):
    count = [0]
    def dfs(node):
        if not node: return (0, 0)
        ls, lc = dfs(node.left)
        rs, rc = dfs(node.right)
        total_sum = ls + rs + node.val
        total_count = lc + rc + 1
        if node.val == total_sum // total_count:
            count[0] += 1
        return (total_sum, total_count)
    dfs(root)
    return count[0]

def invertTree(root):
    if not root: return None
    queue = deque([root])
    while queue:
        node = queue.popleft()
        node.left, node.right = node.right, node.left
        if node.left: queue.append(node.left)
        if node.right: queue.append(node.right)
    return root

def tree_to_list(root):
    if not root: return []
    result, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            result.append(node.val)
            q.append(node.left)
            q.append(node.right)
        else:
            result.append(None)
    while result and result[-1] is None:
        result.pop()
    return result

