def canReach(arr, start):
    n = len(arr)
    queue = deque([start])
    visited = {start}
    while queue:
        idx = queue.popleft()
        if arr[idx] == 0: return True
        for nxt in [idx + arr[idx], idx - arr[idx]]:
            if 0 <= nxt < n and nxt not in visited:
                visited.add(nxt)
                queue.append(nxt)
    return False

