def numOfMinutes(n, headID, manager, informTime):
    subordinates = defaultdict(list)
    for emp, mgr in enumerate(manager):
        if mgr != -1:
            subordinates[mgr].append(emp)
    queue = deque([(headID, 0)])
    max_time = 0
    while queue:
        emp, t = queue.popleft()
        max_time = max(max_time, t)
        for sub in subordinates[emp]:
            queue.append((sub, t + informTime[emp]))
    return max_time

def canFinish(numCourses, prerequisites):
    graph = defaultdict(list)
    in_degree = [0] * numCourses
    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1
    queue = deque(i for i in range(numCourses) if in_degree[i] == 0)
    processed = 0
    while queue:
        node = queue.popleft()
        processed += 1
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
    return processed == numCourses

def distanceK(root, target_val, k):
    # Build undirected adjacency list
    graph = defaultdict(list)
    def build(node, parent):
        if not node: return
        if parent: 
            graph[node.val].append(parent.val)
            graph[parent.val].append(node.val)
        build(node.left, node)
        build(node.right, node)
    build(root, None)
    # BFS from target
    queue = deque([(target_val, 0)])
    visited = {target_val}
    result = []
    while queue:
        node, dist = queue.popleft()
        if dist == k: result.append(node)
        if dist < k:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
    return sorted(result)

