def shortestPath(grid, k):
    rows, cols = len(grid), len(grid[0])
    if rows == 1 and cols == 1: return 0
    queue = deque([(0, 0, k, 0)])  # (r, c, remaining_k, steps)
    visited = {(0, 0, k)}
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]
    while queue:
        r, c, rem, steps = queue.popleft()
        for dr, dc in dirs:
            nr, nc = r+dr, c+dc
            if 0<=nr<rows and 0<=nc<cols:
                nk = rem - grid[nr][nc]
                if nk >= 0 and (nr, nc, nk) not in visited:
                    if nr == rows-1 and nc == cols-1: return steps + 1
                    visited.add((nr, nc, nk))
                    queue.append((nr, nc, nk, steps+1))
    return -1

def numBusesToDestination(routes, source, target):
    if source == target: return 0
    stop_to_routes = defaultdict(set)
    for i, route in enumerate(routes):
        for stop in route:
            stop_to_routes[stop].add(i)
    visited_stops = {source}
    visited_routes = set()
    queue = deque([source])
    buses = 0
    while queue:
        buses += 1
        for _ in range(len(queue)):
            stop = queue.popleft()
            for route_idx in stop_to_routes[stop]:
                if route_idx in visited_routes: continue
                visited_routes.add(route_idx)
                for next_stop in routes[route_idx]:
                    if next_stop == target: return buses
                    if next_stop not in visited_stops:
                        visited_stops.add(next_stop)
                        queue.append(next_stop)
    return -1

def minFlips(mat):
    rows, cols = len(mat), len(mat[0])
    start = 0
    for r in range(rows):
        for c in range(cols):
            if mat[r][c]: start |= (1 << (r * cols + c))
    if start == 0: return 0
    dirs = [(0,0),(0,1),(0,-1),(1,0),(-1,0)]
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        state, flips = queue.popleft()
        for r in range(rows):
            for c in range(cols):
                new_state = state
                for dr, dc in dirs:
                    nr, nc = r+dr, c+dc
                    if 0<=nr<rows and 0<=nc<cols:
                        new_state ^= (1 << (nr * cols + nc))
                if new_state == 0: return flips + 1
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, flips + 1))
    return -1

def minCost(grid):
    rows, cols = len(grid), len(grid[0])
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]  # 1-indexed: right,left,down,up
    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[0][0] = 0
    dq = deque([(0, 0, 0)])  # (cost, r, c)
    while dq:
        cost, r, c = dq.popleft()
        if cost > dist[r][c]: continue
        for i, (dr, dc) in enumerate(dirs):
            nr, nc = r+dr, c+dc
            if 0<=nr<rows and 0<=nc<cols:
                new_cost = cost + (0 if grid[r][c] == i+1 else 1)
                if new_cost < dist[nr][nc]:
                    dist[nr][nc] = new_cost
                    if grid[r][c] == i+1:
                        dq.appendleft((new_cost, nr, nc))
                    else:
                        dq.append((new_cost, nr, nc))
    return dist[rows-1][cols-1]

