        if fire_time[0][0] <= wait: return False
        dist = [[float('inf')] * cols for _ in range(rows)]
        dist[0][0] = wait
        queue = deque([(0, 0, wait)])
        while queue:
            r, c, t = queue.popleft()
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols and grid[nr][nc]!=2 and dist[nr][nc]==float('inf'):
                    arrive = t + 1
                    if nr==rows-1 and nc==cols-1:
                        if arrive <= fire_time[nr][nc]: return True
                    elif arrive < fire_time[nr][nc]:
                        dist[nr][nc] = arrive
                        queue.append((nr, nc, arrive))
        return False

    lo, hi = 0, rows * cols
    if not can_escape(0): return -1
    if can_escape(hi): return 10**9
    while lo < hi:
