    while heap:
        d, node = heapq.heappop(heap)
        if d > dist[node]: continue
        for nb, w in graph[node]:
            nd = d + w
            if nd < dist[nb]:
                dist[nb] = nd
                heapq.heappush(heap, (nd, nb))
    ans = max(dist.values())
    return ans if ans < float('inf') else -1

from collections import defaultdict

def findCheapestPrice(n, flights, src, dst, k):
    prices = [float('inf')] * n
    prices[src] = 0
    for _ in range(k + 1):
        temp = prices[:]
        for u, v, w in flights:
            if prices[u] != float('inf') and prices[u] + w < temp[v]:
                temp[v] = prices[u] + w
        prices = temp
    return prices[dst] if prices[dst] != float('inf') else -1

def findTheCity(n, edges, distanceThreshold):
    INF = float('inf')
    dist = [[INF]*n for _ in range(n)]
    for i in range(n): dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = w
        dist[v][u] = w
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    best_city = -1
    best_count = INF
    for city in range(n):
        count = sum(1 for j in range(n) if city != j and dist[city][j] <= distanceThreshold)
        if count <= best_count:
            best_count = count
            best_city = city
    return best_city

from collections import deque

def minCost(grid):
    rows, cols = len(grid), len(grid[0])
    dir_map = {1:(0,1), 2:(0,-1), 3:(1,0), 4:(-1,0)}
    dist = [[float('inf')]*cols for _ in range(rows)]
    dist[0][0] = 0
    dq = deque([(0, 0, 0)])
    while dq:
        cost, r, c = dq.popleft()
        if cost > dist[r][c]: continue
        for direction, (dr, dc) in dir_map.items():
            nr, nc = r+dr, c+dc
            if 0<=nr<rows and 0<=nc<cols:
                new_cost = cost + (0 if grid[r][c] == direction else 1)
                if new_cost < dist[nr][nc]:
                    dist[nr][nc] = new_cost
                    if grid[r][c] == direction:
                        dq.appendleft((new_cost, nr, nc))
                    else:
                        dq.append((new_cost, nr, nc))
    return dist[rows-1][cols-1]

from collections import deque, defaultdict

def maximumDetonation(bombs):
    n = len(bombs)
    graph = defaultdict(list)
    for i in range(n):
        xi, yi, ri = bombs[i]
        for j in range(n):
            if i == j: continue
            xj, yj, _ = bombs[j]
            if (xi-xj)**2 + (yi-yj)**2 <= ri**2:
                graph[i].append(j)

    def bfs(start):
        visited = {start}
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for nb in graph[node]:
                if nb not in visited:
                    visited.add(nb)
                    queue.append(nb)
        return len(visited)

    return max(bfs(i) for i in range(n))
